            for (int i = 0; i < V; i++) {
                int r = find(parent, i);
                if (compId[r] == -1) {
                    compId[r] = compCount++;
                }
            }

            for (int i = 0; i < V; i++) {
                int r = find(parent, i);
                int cid = compId[r];
                int compNode = N + 1 + cid;
                int station = verts[i];

                adj[station].add(new AdjEdge(compNode, P[c]));
                adj[compNode].add(new AdjEdge(station, 0));
            }
        }

        int totalNodes = N + compCount;
        long INF = Long.MAX_VALUE / 4;
        long[] dist = new long[totalNodes + 1];
        Arrays.fill(dist, INF);
        dist[A] = 0;

        PriorityQueue<State> pq = new PriorityQueue<>();
        pq.add(new State(A, 0));

        while (!pq.isEmpty()) {
            State cur = pq.poll();
            if (cur.dist != dist[cur.id]) continue;

            if (cur.id == B) {
                System.out.println(cur.dist);
                return;
            }

            for (AdjEdge e : adj[cur.id]) {
                long nd = cur.dist + e.w;
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    pq.add(new State(e.to, nd));
                }
            }
        }

        System.out.println(dist[B] >= INF ? -1 : dist[B]);
    }
